"""Build an offline review of in-game presentation and existing original audio."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
out=root/'build/presentation-review'
rows=json.loads((out/'manifest.json').read_text())
assert len({r['id'] for r in rows}) == len(rows)
for r in rows: assert (out/r['file']).is_file()
assert (out/'intro-engine-mix.wav').is_file()
assert (root/'docs/PRESENTATION_REVIEW.md').is_file()
tracks=['wander','battle','aeralis','aeralis_battle','crucible','crucible_battle','station','station_battle','intro']
effects=sorted(p.stem for p in (root/'assets/audio/sfx').glob('*.wav'))
for t in tracks: assert (root/'assets/audio/music'/f'{t}.wav').is_file()
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Frostmere · Presentation review</title><style>
*{box-sizing:border-box}body{margin:0;background:#11171e;color:#e6e0d6;font:16px system-ui}header{padding:40px 5vw;background:linear-gradient(120deg,#263544,#3f2829)}h1{font:44px Georgia;margin:16px 0}p{line-height:1.65;max-width:850px;color:#c8c9c5}small{color:#e6b77d;letter-spacing:2px}nav,section{padding:20px 5vw}nav{position:sticky;top:0;background:#11171ef0;z-index:1}button,select{font:inherit;padding:10px;background:#27333e;border:1px solid #657884;color:#f1e6d5;border-radius:5px;cursor:pointer}button:focus-visible,select:focus-visible{outline:3px solid #e6b77d}main{padding:20px 5vw}#grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:24px}article{background:#1c2833;border:1px solid #465563;border-radius:7px;overflow:hidden}article button{padding:0;border:0;width:100%}img{width:100%;display:block;aspect-ratio:1.6;object-fit:contain}article div{padding:16px}h2{font:24px Georgia;margin:10px 0}audio{display:block;margin:14px 0;max-width:100%}dialog{background:#11171e;color:#eee;max-width:96vw;width:1340px;border:1px solid #697c8b;border-radius:8px}dialog::backdrop{background:#000d}footer{display:flex;gap:12px;align-items:center;justify-content:space-between;padding-top:12px}a{color:#e6b77d}.audio{display:flex;flex-wrap:wrap;gap:38px}label{display:block;margin-bottom:10px}</style>
<header><small>FROSTMERE / REVIEW 04</small><h1>From the first omen to the last furnace.</h1><p>Native game views of the opening, combat cameras, effects and dialogue. The opening has a refined ward beast, fractured cliff faces, batched scenery and a quieter HUD. Critical sound cues can reclaim busy footstep slots; ground-slam fragments share their geometry.</p><p>Existing original synth scores and effects are included below for listening review. Performance traces and test results are recorded separately; M1 and extended human playtesting remain open.</p></header>
<nav><select id="filter" aria-label="Review category"><option>All views</option></select></nav><main><div id="grid"></div></main>
<section><h2>Music and sound</h2><div class="audio"><div><label for="music">Original exploration and battle scores</label><select id="music"></select><audio id="musicPlayer" controls preload="none"></audio></div><div><label for="effects">Interaction and combat cues</label><select id="effects"></select><audio id="effectPlayer" controls preload="none"></audio></div><div><label>Opening · native engine mix</label><audio controls preload="none" src="intro-engine-mix.wav"></audio></div></div><p>Audio starts only when you press Play. <a href="../../docs/PRESENTATION_REVIEW.md">Scope and validation notes</a> · <a href="../landscape-review/index.html">Towns and landscape review</a></p></section>
<dialog id="viewer"><img id="large" alt=""><footer><button id="prev">← Previous</button><span id="caption"></span><button id="next">Next →</button><button id="close">Close</button></footer></dialog><script>
const data=__DATA__,tracks=__TRACKS__,effects=__EFFECTS__,$=id=>document.getElementById(id);let shown=data,active=0;
for(const group of [...new Set(data.map(x=>x.group))]){const o=document.createElement('option');o.textContent=group;$('filter').append(o)}
function show(i){active=(i+shown.length)%shown.length;const r=shown[active];$('large').src=r.file;$('large').alt=r.title;$('caption').textContent=r.title;if(!$('viewer').open)$('viewer').showModal()}
function draw(){shown=data.filter(x=>$('filter').value==='All views'||x.group===$('filter').value);$('grid').replaceChildren();shown.forEach((r,i)=>{const a=document.createElement('article'),b=document.createElement('button'),img=document.createElement('img'),d=document.createElement('div'),s=document.createElement('small'),h=document.createElement('h2');img.src=r.file;img.alt=r.title;img.loading='lazy';b.setAttribute('aria-label','Enlarge '+r.title);b.onclick=()=>show(i);s.textContent=r.group;h.textContent=r.title;b.append(img);d.append(s,h);a.append(b,d);$('grid').append(a)})}
function audioList(id,player,values,folder){for(const v of values){const o=document.createElement('option');o.value=v;o.textContent=v.replaceAll('_',' ');$(id).append(o)}function set(){ $(player).pause();$(player).src='../../assets/audio/'+folder+'/'+$(id).value+'.wav'}$(id).onchange=set;set()}
audioList('music','musicPlayer',tracks,'music');audioList('effects','effectPlayer',effects,'sfx');for(const a of document.querySelectorAll('audio'))a.onplay=()=>{for(const other of document.querySelectorAll('audio'))if(other!==a)other.pause()};
$('filter').onchange=draw;$('prev').onclick=()=>show(active-1);$('next').onclick=()=>show(active+1);$('close').onclick=()=>$('viewer').close();document.onkeydown=e=>{if(!$('viewer').open)return;if(e.key==='ArrowLeft')show(active-1);if(e.key==='ArrowRight')show(active+1)};draw();</script></html>'''
for key,val in [('__DATA__',rows),('__TRACKS__',tracks),('__EFFECTS__',effects)]: page=page.replace(key,json.dumps(val).replace('</','<\\/'))
(out/'index.html').write_text(page)
print(f'PRESENTATION_GALLERY_COMPLETE {len(rows)} views, {len(tracks)} scores, {len(effects)} effects')
